#include <bits/stdc++.h>
#define show(x) std::cout << (x) << '\n';
using namespace std;
typedef long long ll;
typedef pair<ll,ll> pii;
typedef pair<ll,pii> pip;
typedef pair<pii,pii> ppp;
typedef long double ld;
#include <ext/pb_ds/assoc_container.hpp>
#include <ext/pb_ds/tree_policy.hpp>
using namespace __gnu_pbds;

typedef tree<ll, null_type, less<ll>, rb_tree_tag, tree_order_statistics_node_update> ordered_set;

template<typename F, typename C>
struct MinFlowCost {
    struct Edge {
        size_t src, dst, rev;
        F flow, cap;
        C cost;
    };
    int n;
    vector<vector<Edge>> graph;
    vector<C> pi;
    vector<F> dist;
    vector<Edge*> parent;
    MinFlowCost(int n) : n(n), graph(n), pi(n), dist(n), parent(n, nullptr) {}
    void addEdge(size_t s, size_t t, F cap, C cst) {
        graph[s].push_back({s, t, graph[t].size(), 0, cap, cst});
        graph[t].push_back({t, s, graph[s].size() - 1, 0, 0, -cst});
    }
    C get_rcost(const Edge &e) { return e.cost + pi[e.src] - pi[e.dst]; }
    const C INF = numeric_limits<C>::max();
    C runDijkstra(int s, int t) {
        fill(dist.begin(), dist.end(), INF);
        priority_queue<pair<C, int>, vector<pair<C, int>>, greater<>> pq;
        dist[s] = 0;
        pq.push({0, s});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            if (u == t) break;
            for (auto &e : graph[u]) {
                if (e.flow < e.cap && dist[e.dst] > dist[u] + get_rcost(e)) {
                    parent[e.dst] = &e;
                    dist[e.dst] = dist[u] + get_rcost(e);
                    pq.push({dist[e.dst], e.dst});
                }
            }
        }
        return dist[t];
    }
    pair<F, C> maxFlow(int s, int t) {
        F totalFlow = 0;
        C totalCost = 0;
        fill(pi.begin(), pi.end(), 0);
        fill(dist.begin(), dist.end(), 0);
        fill(parent.begin(), parent.end(), nullptr);
        while (runDijkstra(s, t) < INF) {
            for (int u = 0; u < n; ++u)
                if (dist[u] < dist[t]) pi[u] += dist[u] - dist[t];
            F flowCap = numeric_limits<F>::max();
            for (Edge *e = parent[t]; e != nullptr; e = parent[e->src]) {
                flowCap = min(flowCap, e->cap - e->flow);
            }
            for (Edge *e = parent[t]; e != nullptr; e = parent[e->src]) {
                e->flow += flowCap;
                graph[e->dst][e->rev].flow -= flowCap;
            }
            totalFlow += flowCap;
            totalCost += flowCap * (pi[t] - pi[s]);
        }
        return {totalFlow, totalCost};
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    MinFlowCost<int, int> g((n + 2) * 102);
    for (int i = 0; i < 102; ++i)
        g.addEdge((i * (n + 2)) + 1, i * (n + 2), 100, i * c);
    for (int i = 0; i < 101; ++i)
        for (int j = 0; j <= n; ++j)
            g.addEdge(j + (i * (n + 2)), j + ((i + 1) * (n + 2)), 100, 0);
    for (int i = 0; i < k; ++i) {
        int u; cin >> u;
        g.addEdge(n + 1, u, 1, 0);
    }
    for (int i = 0; i < m; ++i) {
        int u, v; cin >> u >> v;
        for (int j = 0; j < 101; ++j)
            for (int f = 0; f < k; ++f) {
                g.addEdge(u + (j * (n + 2)), v + ((j + 1) * (n + 2)), 1, ((2 * f) + 1) * d);
                g.addEdge(v + (j * (n + 2)), u + ((j + 1) * (n + 2)), 1, ((2 * f) + 1) * d);
            }
    }
    auto [flow, cost] = g.maxFlow(n + 1, (101 * (n + 2)));
    show(cost);
    return 0;
}
